235: // checkNetmapConfExists checks if the network mapper configuration file exists.
236: // If not, if attempts to generate the file using generateNetmapConfig.
237: func checkNetmapConfExists() (NetworkNameMapper, error) {
238: 	pathNetmap := workstationNetmapConfPath()
239: 
240: 	// Check if the default network mapper configuration file exists.
241: 	if _, err := os.Stat(pathNetmap); os.IsNotExist(err) {
242: 		log.Printf("A network mapper configuration file does not exist in the default path: %s", pathNetmap)
243: 
244: 		// The file does not exist, check the alternate configuration path.
245: 		libpath, _ := workstationVMwareRoot()
246: 		pathNetworking := filepath.Join(libpath, "networking")
247: 		log.Printf("Checking alternate path for network mapper configuration file: %s", pathNetworking)
248: 		if _, err := os.Stat(pathNetworking); err == nil {
249: 			// Alternate networking configuration path exists. Using this path.
250: 			log.Printf("Located the network mapper configuration file: %s", pathNetworking)
251: 			fd, err := os.Open(pathNetworking)
252: 			if err != nil {
253: 				return nil, err
254: 			}
255: 			defer fd.Close()
256: 
257: 			// Then we pass the handle to the networking configuration parser.
258: 			return ReadNetworkingConfig(fd)
259: 		} else if runtime.GOOS == "windows" {
260: 			// Neither the default nor alternate exists.
261: 			// Generate the network mapper configuration file in the default path.
262: 			log.Printf("Generating a network mapper configuration file in the default path: %s", pathNetmap)
263: 			pathNetmap, err := generateNetmapConfig()
264: 			if err != nil {
265: 				log.Fatalf("error generating the absent network configuration file: %v", err)
266: 				return nil, err
267: 			}
268: 			// If the file exists, attempt to read the newly generated
269: 			// network mapper configuration file.
270: 			return ReadNetmapConfig(pathNetmap)
271: 		} else {
272: 			// For non-Windows, if neither the default nor alternate
273: 			// configuration paths exist, return an error.
274: 			return nil, fmt.Errorf("error determining network mappings from files in path: %s", libpath)
275: 		}
276: 	} else if err != nil {
277: 		// There was an error other than the file not existing.
278: 		return nil, err
279: 	}
280: 
281: 	// If the default network mapper configuration file exists, read the configuration.
282: 	log.Printf("Located the network mapper configuration file: %s", pathNetmap)
283: 	return ReadNetmapConfig(pathNetmap)
284: }
