286: // generateNetmapConfig creates the network mapper configuration file in the
287: // default path using the netmapTemplate and returns the path of the created file.
288: func generateNetmapConfig() (string, error) {
289: 	var paths []string
290: 	if os.Getenv("ProgramData") != "" {
291: 		paths = append(paths, filepath.Join(os.Getenv("ProgramData"), "VMware"))
292: 	}
293: 
294: 	networks := []NetmapConfig{
295: 		{0, "Bridged", "vmnet0"},
296: 		{1, "HostOnly", "vmnet1"},
297: 		{8, "NAT", "vmnet8"},
298: 	}
299: 	for i := 2; i <= 19; i++ {
300: 		if i != 8 {
301: 			networks = append(networks, NetmapConfig{i, fmt.Sprintf("VMNet%d", i), fmt.Sprintf("vmnet%d", i)})
302: 		}
303: 	}
304: 
305: 	sort.Slice(networks, func(i, j int) bool {
306: 		return networks[i].Index < networks[j].Index
307: 	})
308: 
309: 	t, err := template.New("netmap").Parse(netmapTemplate)
310: 	if err != nil {
311: 		return "", err
312: 	}
313: 
314: 	var sb strings.Builder
315: 	if err := t.Execute(&sb, networks); err != nil {
316: 		return "", err
317: 	}
318: 	netmapContent := []byte(sb.String())
319: 
320: 	var pathNetmap string
321: 	for _, basePath := range paths {
322: 		path := filepath.Join(basePath, "netmap.conf")
323: 		if err := os.MkdirAll(basePath, 0755); err != nil {
324: 			continue // Skip to the next path on error.
325: 		}
326: 		if err := os.WriteFile(path, netmapContent, 0644); err != nil {
327: 			continue // Skip to the next path on error.
328: 		}
329: 
330: 		// If the file exists, set pathNetmap and break the loop.
331: 		if _, err := os.Stat(path); err == nil {
332: 			pathNetmap = path
333: 			break // Exit the loop since the file was successfully created.
334: 		}
335: 	}
336: 
337: 	if pathNetmap != "" {
338: 		return pathNetmap, nil
339: 	} else {
340: 		return "", fmt.Errorf("no valid path found for generating the network mapper configuration file")
341: 	}
342: }

