	// Check if the network mapper configuration file exists.
	mapper, err := checkNetmapConfExists()
	if err == nil {
		return mapper, nil
	}

	if runtime.GOOS != "windows" || !errors.Is(err, os.ErrNotExist) {
		return nil, fmt.Errorf("error reading network mapper configuration: %w", err)
