	pathNetmap := workstationNetmapConfPath()
	log.Printf("Generating a network mapper configuration file in the default path: %s", pathNetmap)
	pathNetmap, err = generateNetmapConfig()
	if err != nil {
		return nil, fmt.Errorf("error generating the absent network configuration file: %w", err)
	}

	return ReadNetmapConfig(pathNetmap)
}

